<?php /* * ========================================================= * api/get_private.php * Получение приватного диалога * PHP 5.6.4 * ========================================================= */ require_once __DIR__ . '/../config/auth.php'; requireLogin(); checkBlocked(); updateLastActivity(); header('Content-Type: application/json; charset=utf-8'); $myId = currentUserId(); $targetId = isset($_GET['user_id']) ? (int) $_GET['user_id'] : 0; /* * ========================================================= * ПРОВЕРКА СОБЕСЕДНИКА * ========================================================= */ if ( $targetId <= 0 || $targetId === $myId ) { echo json_encode( array(), JSON_UNESCAPED_UNICODE ); exit; } /* * ========================================================= * ПРОВЕРЯЕМ, ЧТО ПОЛЬЗОВАТЕЛЬ СУЩЕСТВУЕТ * ========================================================= */ $stmt = $pdo->prepare( 'SELECT id FROM users WHERE id = ? AND is_blocked = 0 LIMIT 1' ); $stmt->execute( array( $targetId ) ); $targetUser = $stmt->fetch(); if (!$targetUser) { echo json_encode( array(), JSON_UNESCAPED_UNICODE ); exit; } /* * ========================================================= * ПОЛУЧАЕМ ДИАЛОГ * ========================================================= */ $stmt = $pdo->prepare( 'SELECT pm.id, pm.sender_id, pm.receiver_id, pm.message, pm.created_at, sender.username AS sender_name, receiver.username AS receiver_name FROM private_messages pm INNER JOIN users sender ON sender.id = pm.sender_id INNER JOIN users receiver ON receiver.id = pm.receiver_id WHERE ( pm.sender_id = ? AND pm.receiver_id = ? ) OR ( pm.sender_id = ? AND pm.receiver_id = ? ) ORDER BY pm.created_at ASC, pm.id ASC LIMIT 100' ); $stmt->execute( array( $myId, $targetId, $targetId, $myId ) ); $messages = $stmt->fetchAll(); /* * ========================================================= * ПОМЕЧАЕМ ПРИВАТНЫЕ СООБЩЕНИЯ ПРОЧИТАННЫМИ * ========================================================= */ $stmt = $pdo->prepare( 'UPDATE private_messages SET is_read = 1 WHERE receiver_id = ? AND sender_id = ? AND is_read = 0' ); $stmt->execute( array( $myId, $targetId ) ); /* * ========================================================= * ПОМЕЧАЕМ ЛИЧНЫЕ СООБЩЕНИЯ ПРОЧИТАННЫМИ * * Это важно для счётчика. * personal_messages содержит архив входящих ЛС. * ========================================================= */ $stmt = $pdo->prepare( 'UPDATE personal_messages SET is_read = 1 WHERE receiver_id = ? AND sender_id = ? AND is_read = 0' ); $stmt->execute( array( $myId, $targetId ) ); /* * ========================================================= * ОТВЕТ * ========================================================= */ echo json_encode( $messages, JSON_UNESCAPED_UNICODE ); exit; ?>